package com.mendes.scheduling_platform.auth;
import com.mendes.scheduling_platform.exception.*; import com.mendes.scheduling_platform.security.JwtService; import com.mendes.scheduling_platform.tenant.*; import com.mendes.scheduling_platform.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/auth") public class AuthController { private final UserRepository users; private final TenantRepository tenants; private final PasswordEncoder encoder; private final JwtService jwt; public AuthController(UserRepository u,TenantRepository t,PasswordEncoder e,JwtService j){users=u;tenants=t;encoder=e;jwt=j;} public record Login(@NotBlank @Email String email,@NotBlank String password,@NotBlank String tenantSlug){} public record Token(String token,String type){} @PostMapping("/login") Token login(@Valid @RequestBody Login in){Tenant t=tenants.findBySlug(in.tenantSlug()).orElseThrow(()->new BusinessException("Credenciais inválidas")); if(t.getStatus()!=Tenant.TenantStatus.ACTIVE)throw new BusinessException("Tenant suspenso"); User u=users.findByTenantIdAndEmailIgnoreCase(t.getId(),in.email()).filter(x->encoder.matches(in.password(),x.getPassword())).orElseThrow(()->new BusinessException("Credenciais inválidas")); return new Token(jwt.issue(u.getEmail(),u.getTenantId(),u.getRole().name(),false),"Bearer");} }
